import java.util.ArrayList;
import java.util.Collection;
import java.util.List;

// ANTI-PATTERN: Inheriting from a concrete library class
class BrokenInstrumentedList<E> extends ArrayList<E> {
    private int addCount = 0;

    @Override
    public boolean add(E e) {
        addCount++;
        return super.add(e);
    }

    @Override
    public boolean addAll(Collection<? extends E> c) {
        // BUG: In ArrayList, addAll() internally calls add()!
        // If we increment here AND super calls add(), count is doubled!
        addCount += c.size();
        return super.addAll(c);
    }

    public int getAddCount() { return addCount; }
}

public class FragileBaseDemo {
    public static void main(String[] args) {
        BrokenInstrumentedList<String> list = new BrokenInstrumentedList<>();
        list.addAll(List.of("A", "B", "C"));

        // Expected: 3. Actual: 6 (if ArrayList.addAll calls add())!
        System.out.println("Add Count: " + list.getAddCount());
    }
}

