import java.util.ArrayList;
import java.util.Collection;
import java.util.List;

// SAFE PATTERN: Composition and Delegation
class SafeInstrumentedList<E> {
    // Composed internal instance
    private final List<E> internalList = new ArrayList<>();
    private int addCount = 0;

    public void add(E e) {
        addCount++;
        internalList.add(e); // Explicit delegation
    }

    public void addAll(Collection<? extends E> c) {
        addCount += c.size();
        internalList.addAll(c); // Independent of internal implementation!
    }

    public int getAddCount() { return addCount; }
    public int size() { return internalList.size(); }
}

public class CompositionSafeDemo {
    public static void main(String[] args) {
        SafeInstrumentedList<String> list = new SafeInstrumentedList<>();
        list.addAll(List.of("A", "B", "C"));

        System.out.println("Items in list: " + list.size());
        System.out.println("Accurate Add Count: " + list.getAddCount());
    }
}

