import java.util.ArrayList;
import java.util.List;

class SafeStack {
    private final List<String> storage = new ArrayList<>();

    public void push(String item) {
        storage.add(item);
    }

    public String pop() {
        if (storage.isEmpty()) throw new IllegalStateException("Stack is empty");
        return storage.remove(storage.size() - 1);
    }

    public int size() {
        return storage.size();
    }
}

public class Practice1 {
    public static void main(String[] args) {
        SafeStack stack = new SafeStack();
        stack.push("Alpha");
        stack.push("Beta");
        System.out.println("Popped: " + stack.pop());
        System.out.println("Remaining size: " + stack.size());
    }
}

interface EmployeeRole {
    String getRoleTitle();
    double calculateBonus(double baseSalary);
}

class DeveloperRole implements EmployeeRole {
    @Override
    public String getRoleTitle() { return "Senior Developer"; }
    @Override
    public double calculateBonus(double baseSalary) { return baseSalary * 0.10; }
}

class ManagerRole implements EmployeeRole {
    @Override
    public String getRoleTitle() { return "Engineering Manager"; }
    @Override
    public double calculateBonus(double baseSalary) { return baseSalary * 0.25; }
}

class Employee {
    private final String name;
    private final double baseSalary;
    private EmployeeRole role;

    public Employee(String name, double baseSalary, EmployeeRole role) {
        this.name = name;
        this.baseSalary = baseSalary;
        this.role = role;
    }

    public void setRole(EmployeeRole role) { this.role = role; }
    public double getTotalCompensation() { return baseSalary + role.calculateBonus(baseSalary); }
    public void printProfile() {
        System.out.println(name + " (" + role.getRoleTitle() + "): $" + getTotalCompensation());
    }
}

public class DynamicRoleApp {
    public static void main(String[] args) {
        Employee emp = new Employee("Dave", 100000.0, new DeveloperRole());
        emp.printProfile();

        emp.setRole(new ManagerRole());
        emp.printProfile();
    }
}

interface Engine {
    String start();
}

class ElectricEngine implements Engine {
    @Override
    public String start() { return "Silent Electric Drive"; }
}

class GasEngine implements Engine {
    @Override
    public String start() { return "V8 Roar"; }
}

class Vehicle {
    private final String model;
    private final Engine engine;
    public Vehicle(String model, Engine engine) {
        this.model = model;
        this.engine = engine;
    }
    public void drive() {
        System.out.println(model + " moving with " + engine.start());
    }
}

public class BridgeApp {
    public static void main(String[] args) {
        Vehicle car1 = new Vehicle("Tesla Model S", new ElectricEngine());
        car1.drive();

        Vehicle car2 = new Vehicle("Ford Mustang", new GasEngine());
        car2.drive();
    }
}

