import java.util.HashMap;

// BUG: Extending HashMap exposes all raw map mutations
class StringDictionary extends HashMap<String, Object> {
    public void addEntry(String k, String v) {
        put(k, v);
    }
}

public class DictBugDemo {
    public static void main(String[] args) {
        StringDictionary dict = new StringDictionary();
        dict.addEntry("host", "localhost");
        // Type safety breached via inherited put:
        dict.put("port", 8080); // Corrupts string dictionary!
        System.out.println("Host: " + dict.get("host"));
    }
}

