import java.util.HashMap;
import java.util.Map;

class StringDictionary {
    private final Map<String, String> internalMap = new HashMap<>();

    public void set(String key, String val) {
        internalMap.put(key, val);
    }

    public String get(String key) {
        return internalMap.get(key);
    }
}

public class DictBugDemo {
    public static void main(String[] args) {
        StringDictionary dict = new StringDictionary();
        dict.set("host", "localhost");
        System.out.println("Host: " + dict.get("host"));
    }
}

interface DataWriter {
    void write(String data);
}

class FileWriter implements DataWriter {
    @Override
    public void write(String data) {
        System.out.println("Writing to disk: " + data);
    }
}

class AuditedDataWriter implements DataWriter {
    private final DataWriter delegate;
    private int writeCount = 0;

    public AuditedDataWriter(DataWriter delegate) {
        this.delegate = delegate;
    }

    @Override
    public void write(String data) {
        writeCount++;
        System.out.println("[AUDIT] Action #" + writeCount);
        delegate.write(data);
    }

    public int getWriteCount() { return writeCount; }
}

public class DecoratorApp {
    public static void main(String[] args) {
        AuditedDataWriter auditor = new AuditedDataWriter(new FileWriter());
        auditor.write("User logged in");
        auditor.write("Password changed");
        System.out.println("Total Audited: " + auditor.getWriteCount());
    }
}
